/// <summary>
/// MET logistics postal address form extension
/// </summary>
[ExtensionOf(formStr(LogisticsPostalAddress))]
final class METLogisticsPostalAddress_Form_Extension
{
}

Method.Source:
/// <summary>
/// Form init to enable or disable kleber controls
/// </summary>
public void init()
{
    next init();

    Args args = this.args();

    if (args.menuItemName() == menuItemDisplayStr(CustDirPartyPostalAddressEdit) || args.menuItemName() == menuItemDisplayStr(CustDirPartyPostalAddressNew)) 
    {
        FormGroupControl addressSearch = this.design().controlName(formcontrolstr(LogisticsPostalAddress, AddressSearch)) as FormGroupControl;
        addressSearch.visible(true);
    }
}
